'use strict';

const fs = require('fs');
const path = require('path');

const file = path.join(__dirname, '..', 'public', 'runtime-config.js');
const serverUrl = String(process.env.GAME_SERVER_URL || '').trim();
const wsUrl = String(process.env.GAME_SERVER_WS_URL || '').trim();
const safe = (value) => JSON.stringify(value.replace(/\s+/g, ''));

const contents = [
  '/* Generated by npm run build:pages; do not place secrets here. */',
  'window.__LITTLE_SUPERMARKET_CONFIG__ = {',
  `  serverUrl: ${safe(serverUrl)},`,
  `  wsUrl: ${safe(wsUrl)}`,
  '};',
  ''
].join('\n');

fs.writeFileSync(file, contents, 'utf8');
console.log(`GitHub Pages runtime config written: ${serverUrl ? serverUrl : '(offline-only unless ?serverUrl= is supplied)'}`);
